def backfill_existing_requests(apps, schema_editor):
    """Demandes antérieures : date de la demande = date de création, et une
    référence BES-<année>-<n°> attribuée dans l'ordre chronologique."""
    DisbursementRequest = apps.get_model('finance', 'DisbursementRequest')
    counters = {}
    for request in DisbursementRequest.objects.order_by('created_at'):
        request.request_date = request.created_at.date()
        year = request.request_date.year
        counters[year] = counters.get(year, 0) + 1
        request.reference = f'BES-{year}-{counters[year]:04d}'
        request.save(update_fields=['request_date', 'reference'])


